function reloadWatchDirs(fs, root) {
	const dirs = [];
	const walk = (dir) => {
		dirs.push(dir);
		let names;
		try {
			names = fs.readdirSync(dir);
		} catch {
			return;
		}
		for (const name of names) {
			if (SKIP_DIRS.has(name)) continue;
			const full = dir === "/" ? "/" + name : dir + "/" + name;
			try {
				if (fs.statSync(full).isDirectory()) walk(full);
			} catch {}
		}
	};
	walk(root);
	return dirs;
}
